 // High-quality compression using browser-image-compression library
 async function compress(){
  var targetBytes=mode==='pct'?Math.round(file.size*(1-pct.value/100)):Math.round(parseFloat(kb.value)*1024);
  if(!targetBytes||targetBytes<5120)return err('Enter a target of at least 5 KB.');

  var desiredType=(window.__outfmt==='webp')?'image/webp':'image/jpeg';
  var desiredExt=desiredType==='image/webp'?'webp':'jpg';

  // Already under target: keep original if format matches choice; otherwise convert to requested format
  if(file.size<=targetBytes){
    if(file.type===desiredType){
      result(file,file.name,size(file.size)+' · already under '+size(targetBytes)+' — original kept, not re-compressed');
      return;
    }
    // Respect "Save as JPG/WebP" even when already small enough
    var c0=draw(img.naturalWidth,img.naturalHeight,desiredType==='image/jpeg');
    var b0=await blob(c0,desiredType,0.95);
    if(b0&&b0.type===desiredType&&b0.size<=targetBytes){
      result(b0,base()+'.'+desiredExt,size(file.size)+' → '+size(b0.size)+' · converted to '+desiredExt.toUpperCase()+' (already under target)');
      return;
    }
    // Converting would push the file OVER the target (e.g. small PNG -> larger JPG): fall through to the quality search below.
    if(!b0||b0.type!==desiredType){
      result(file,file.name,size(file.size)+' · already under '+size(targetBytes)+' — original kept, not re-compressed');
      return;
    }
  }

  // Encode at one size. Binary-search quality between 0.95 and 0.10 for the largest quality that fits.
  async function encodeUnder(c,type){
    var HI=0.95,LO=0.1;
    var top=await blob(c,type,HI);
    if(!top||top.type!==type)return null;          // browser cannot encode this type
    if(top.size<=targetBytes)return {blob:top,q:HI,ok:true};
    var floor=await blob(c,type,LO);
    if(!floor)return null;
    if(floor.size>targetBytes)return {blob:floor,q:LO,ok:false};  // even quality 0.1 is too big
    var best=floor,bq=LO,l=LO,h=HI;
    for(var k=0;k<9;k++){
      var m=(l+h)/2,t=await blob(c,type,m);
      if(t&&t.size<=targetBytes){best=t;bq=m;l=m}else h=m;
    }
    return {blob:best,q:bq,ok:true};
  }

  var types=(window.__outfmt==='webp')?['image/webp','image/jpeg']:['image/jpeg'];
  var bestOverall=null; // track smallest result across scales
  var scale=1.0;
  var origW=img.naturalWidth,origH=img.naturalHeight;

  while(scale>=0.1-1e-9){
    var w=Math.max(1,Math.round(origW*scale));
    var h=Math.max(1,Math.round(origH*scale));
    var res=null,usedType='image/jpeg',c=null;
    for(var ti=0;ti<types.length&&!res;ti++){
      c=draw(w,h,types[ti]==='image/jpeg');
      res=await encodeUnder(c,types[ti]);
      if(res)usedType=types[ti];
    }
    if(res){
      if(!bestOverall||res.blob.size<bestOverall.blob.size){
        bestOverall={blob:res.blob,q:res.q,scale:scale,type:usedType,ok:res.ok,w:w,h:h};
      }
      if(res.ok&&res.blob.size<=targetBytes){
        var out=res.blob,ext=usedType==='image/webp'?'webp':'jpg';
        var dims=w+'×'+h+' px';
        var scaleNote=scale<1?' · scaled to '+Math.round(scale*100)+'%':'';
        result(out,base()+'-compressed.'+ext,size(file.size)+' → '+size(out.size)+' · '+dims+scaleNote+' · quality '+Math.round(res.q*100)+'%');
        return;
      }
    }
    // Quality search failed at this scale → reduce resolution by 10% and retry
    scale=Math.round((scale-0.1)*10)/10;
    if(scale>=0.1)console.log('Target not reached, trying scale',scale);
  }

  // Even 10% scale failed — return smallest found + warning with clickable Try resizing
  if(!bestOverall)return err('Your browser could not compress this image. Try a different file.');
  var out=bestOverall.blob,ext=bestOverall.type==='image/webp'?'webp':'jpg';
  var dims=bestOverall.w+'×'+bestOverall.h+' px';
  var scaleNote=bestOverall.scale<1?' · scaled to '+Math.round(bestOverall.scale*100)+'%':'';
  var warn='Could not reach '+size(targetBytes)+'. Smallest possible is '+size(out.size)+'. <button type="button" id="tryResizeBtn" style="background:none;border:none;color:#b45309;text-decoration:underline;cursor:pointer;font:inherit;font-weight:600;padding:0">Try resizing</button> the image or allowing lower quality.';
  result(out,base()+'-compressed.'+ext,size(file.size)+' → '+size(out.size)+' · '+dims+scaleNote+' · quality '+Math.round(bestOverall.q*100)+'%',warn);
 }

 async function convert(){
  var type='image/'+fmt;
  // Prefer library for better quality when converting to lossy formats
  if((fmt==='jpeg'||fmt==='webp') && typeof imageCompression!=='undefined'){
    try{
      var options={
        maxSizeMB:50,
        maxWidthOrHeight:Math.max(img.naturalWidth,img.naturalHeight),
        useWebWorker:true,
        initialQuality:0.92,
        alwaysKeepResolution:true,
        fileType:type
      };
      var out=await imageCompression(file,options);
      if(out&&out.type===type){
        result(out,base()+'.'+EXT[fmt],file.type.replace('image/','').toUpperCase()+' → '+fmt.toUpperCase()+' · '+size(out.size));
        return;
      }
    }catch(e){}
  }
  // Canvas fallback with high quality
  var c=draw(img.naturalWidth,img.naturalHeight,fmt==='jpeg');
  var b=await blob(c,type,fmt==='png'?undefined:0.92);
  if(!b||(fmt!=='png'&&b.type!==type))return err('Your browser cannot create this format. Try JPG or PNG.');
  result(b,base()+'.'+EXT[fmt],file.type.replace('image/','').toUpperCase()+' → '+fmt.toUpperCase()+' · '+size(b.size));
 }

 async function resize(){
  var w=Math.round($('rw').value),h=Math.round($('rh').value);
  if(!(w>=1&&h>=1&&w<=8000&&h<=8000))return err('Enter a width and height between 1 and 8000 px.');
  var preferType=/^image\/(jpeg|png|webp)$/.test(file.type)?file.type:'image/png';
  var f=preferType.slice(6);

  if(resizeMode==='crop'){
   var iw=img.naturalWidth,ih=img.naturalHeight,sx,sy,sw,sh,gr=GAL.cropFor(file);
   if(gr){sx=gr.l*iw;sy=gr.t*ih;sw=(gr.r-gr.l)*iw;sh=(gr.b-gr.t)*ih}
   else{
    // Not fine-tuned by hand: centered crop in the chosen shape, so the same size applies to every image automatically.
    var tr=w/h,rr=iw/ih;sx=0;sy=0;sw=iw;sh=ih;
    if(rr>tr){sw=ih*tr;sx=(iw-sw)/2}else if(rr<tr){sh=iw/tr;sy=(ih-sh)/2}
   }
   if(sw<1||sh<1)return err('Move the crop box inside the image.');
   var cropCanvas=document.createElement('canvas');cropCanvas.width=w;cropCanvas.height=h;var cropCtx=cropCanvas.getContext('2d');cropCtx.imageSmoothingEnabled=true;cropCtx.imageSmoothingQuality='high';
   if(preferType==='image/jpeg'){cropCtx.fillStyle='#fff';cropCtx.fillRect(0,0,w,h)}
   cropCtx.drawImage(img,sx,sy,sw,sh,0,0,w,h);
   var cropBlob=await blob(cropCanvas,preferType,preferType==='image/png'?undefined:0.92);
   result(cropBlob,base()+'-'+w+'x'+h+'-crop.'+EXT[f],Math.round(sw)+'×'+Math.round(sh)+' crop → '+w+'×'+h+' px · '+size(cropBlob.size));return;
  }


  // Use library when downscaling for better quality
  if(typeof imageCompression!=='undefined' && (w<img.naturalWidth||h<img.naturalHeight)){
    try{
      var options={
        maxSizeMB:40,
        maxWidthOrHeight:Math.max(w,h),
        useWebWorker:true,
        initialQuality:0.92,
        alwaysKeepResolution:false,
        fileType:preferType
      };
      var out=await imageCompression(file,options);
      // Final exact resize with high-quality canvas
      var tmp=new Image();
      var u=URL.createObjectURL(out);
      await new Promise(function(res,rej){tmp.onload=res;tmp.onerror=rej;tmp.src=u});
      var c=document.createElement('canvas');c.width=w;c.height=h;
      var x=c.getContext('2d');
      x.imageSmoothingEnabled=true;x.imageSmoothingQuality='high';
      if(f==='jpeg'){x.fillStyle='#fff';x.fillRect(0,0,w,h)}
      x.drawImage(tmp,0,0,w,h);
      URL.revokeObjectURL(u);
      var b=await blob(c,preferType,f==='png'?undefined:0.92);
      result(b,base()+'-'+w+'x'+h+'.'+EXT[f],img.naturalWidth+'×'+img.naturalHeight+' → '+w+'×'+h+' px · '+size(b.size));
      return;
    }catch(e){}
  }

  // Pure canvas high-quality path
  var c=draw(w,h,f==='jpeg');
  var b=await blob(c,preferType,f==='png'?undefined:0.92);
  result(b,base()+'-'+w+'x'+h+'.'+EXT[f],img.naturalWidth+'×'+img.naturalHeight+' → '+w+'×'+h+' px · '+size(b.size));
 }
 async function qr(text,label){
  if(!text.trim())return err('Please enter some text first.');
  if(typeof qrcode==='undefined')return err('The QR library did not load. Check your internet and reload.');
  try{
   if(qrcode.stringToBytesFuncs&&qrcode.stringToBytesFuncs['UTF-8'])qrcode.stringToBytes=qrcode.stringToBytesFuncs['UTF-8'];
   var q=qrcode(0,'M');q.addData(text.trim());q.make();
   var n=q.getModuleCount(),s=Math.max(3,Math.floor(560/(n+8))),c=document.createElement('canvas');
   c.width=c.height=(n+8)*s;var x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.fillStyle='#000';
   for(var r=0;r<n;r++)for(var k=0;k<n;k++)if(q.isDark(r,k))x.fillRect((k+4)*s,(r+4)*s,s,s);
   result(await blob(c,'image/png'),'qr-code.png',label+' · '+c.width+'×'+c.height+' px');
  }catch(e){err('This text is too long for a QR code. Please shorten it.')}
 }
