 function bindFile(selectId,dropId,clearId,acceptFn,cb){
  var inp=$(selectId),drop=$(dropId),clear=$(clearId); if(!inp||!drop)return;
  $(selectId.replace('file','s'));
  function set(f){if(!f)return;if(acceptFn&&!acceptFn(f)){err('Please choose a supported file.');return}cb(f)}
  drop.onclick=function(){inp.click()}; inp.onchange=function(){set(inp.files[0])};
  ['dragover','dragenter'].forEach(function(v){drop.addEventListener(v,function(e){e.preventDefault();drop.classList.add('on')})});
  ['dragleave','drop'].forEach(function(v){drop.addEventListener(v,function(e){e.preventDefault();drop.classList.remove('on')})});
  drop.addEventListener('drop',function(e){set(e.dataTransfer.files[0])}); if(clear)clear.onclick=function(){inp.value='';drop.classList.remove('on');cb(null)};
 }
