 /* ---------------- Shared PDF selection ----------------
    Single source of truth for Compress, Merge, Split, PDF to Image and Edit PDF.
    PDFShared.files holds the ORIGINAL selected PDFs in order. Each tool reads from it when it runs.
    Edit PDF keeps a separate, clearly labelled WORKING copy (EP) of PDFShared.files[0]; it is never
    discarded without asking. Image to PDF / Scan Document use the same gallery shell for image previews, while keeping their own image-processing state. */
 var PS=window.PDFShared={
  files:[],tool:'pdfcompress',cache:new Map(),subs:[],edit:null,
  first:function(){return PS.files[0]||null},
  on:function(fn){PS.subs.push(fn)},
  emit:function(kind,origin){PS.subs.slice().forEach(function(fn){try{fn(kind,origin)}catch(e){console.error(e)}})},
  isPdf:function(f){return !!f&&(f.type==='application/pdf'||/\.pdf$/i.test(f.name||''))},
  same:function(list){return list.length===PS.files.length&&list.every(function(f,i){return f===PS.files[i]})},
  confirmDiscard:function(action){
   if(!PS.edit||!PS.edit.isDirty())return true;
   return window.confirm('Edit PDF has unsaved page changes (rotated, deleted, reordered, edited or added pages). '+action+' will discard them. Continue?')},
  resetInputs:function(){['pdfcfile','pdfsfile','pdfmfiles','pdfifile'].forEach(function(id){var el=$(id);if(el)el.value=''})},
  prune:function(){PS.cache.forEach(function(v,k){if(PS.files.indexOf(k)<0)PS.cache.delete(k)})},
  setFiles:function(list,origin){
   list=Array.prototype.slice.call(list||[]).filter(PS.isPdf);
   if(!list.length)return false;
   if(PS.same(list))return true;
   if(!PS.confirmDiscard('Selecting another PDF')){PS.resetInputs();return false}
   if(PS.edit)PS.edit.reset();
   PS.files=list;PS.prune();PS.emit('select',origin);return true},
  clear:function(origin,force){
   if(!force&&!PS.confirmDiscard('Clearing the PDF'))return false;
   PS.files=[];PS.cache.clear();if(PS.edit)PS.edit.reset();msg.textContent='';PS.emit('clear',origin);return true},
  move:function(i,d){
   var j=i+d;if(i<0||j<0||i>=PS.files.length||j>=PS.files.length)return false;
   var next=PS.files.slice();next.splice(j,0,next.splice(i,1)[0]);
   if(next[0]!==PS.files[0]){if(!PS.confirmDiscard('Putting a different PDF first'))return false;if(PS.edit)PS.edit.reset()}
   PS.files=next;PS.emit('order');return true},
  /* parsed pdf.js document, cached per File so switching tools never re-reads the file */
  load:function(file){
   var c=PS.cache.get(file);if(!c){c={pages:{}};PS.cache.set(file,c)}
   if(!c.doc){c.doc=(async function(){await loadFor('pdf');var bytes=new Uint8Array(await file.arrayBuffer());var doc=await pdfjsLib.getDocument({data:bytes.slice()}).promise;return {doc:doc,bytes:bytes}})();
    c.doc.catch(function(){if(PS.cache.get(file)===c)PS.cache.delete(file)})}
   return c.doc},
  /* page preview (data URL, same size the Edit gallery has always used), cached per File + page */
  renderPage:function(file,n){
   var c=PS.cache.get(file);if(!c){c={pages:{}};PS.cache.set(file,c)}
   if(!c.pages[n]){c.pages[n]=(async function(){var d=await PS.load(file),pg=await d.doc.getPage(n),vp=pg.getViewport({scale:1}),v2=pg.getViewport({scale:Math.min(1.35,1000/Math.max(vp.width,vp.height))}),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(v2.width));cv.height=Math.max(1,Math.round(v2.height));
     await pg.render({canvasContext:cv.getContext('2d',{alpha:false}),viewport:v2}).promise;return cv.toDataURL('image/jpeg',0.9)})();
    c.pages[n].catch(function(){if(c.pages)delete c.pages[n]})}
   return c.pages[n]}
 };
