 async function compressPdfLight(file){
  var a=await pdfApi().PDFDocument.load(await file.arrayBuffer(),{ignoreEncryption:true});
  var out=await a.save({useObjectStreams:true,addDefaultPage:false});
  return new Blob([out],{type:'application/pdf'});
 }

 async function compressPdfStrong(file){
  if(!window.pdfjsLib)throw Error('PDF renderer not loaded');
  var data=await file.arrayBuffer();
  var pdf=await pdfjsLib.getDocument({data:data}).promise;
  var newPdf=await pdfApi().PDFDocument.create();
  var scale=1.5; // ~108-150 DPI feel; balance size vs clarity
  var quality=0.72;
  for(var i=1;i<=pdf.numPages;i++){
   msg.textContent='Strong compress… page '+i+' / '+pdf.numPages;
   var page=await pdf.getPage(i);
   var viewport=page.getViewport({scale:scale});
   var canvas=document.createElement('canvas');
   canvas.width=Math.floor(viewport.width);
   canvas.height=Math.floor(viewport.height);
   var ctx=canvas.getContext('2d');
   ctx.fillStyle='#fff';
   ctx.fillRect(0,0,canvas.width,canvas.height);
   await page.render({canvasContext:ctx,viewport:viewport}).promise;
   var jpeg=await new Promise(function(res){canvas.toBlob(res,'image/jpeg',quality)});
   if(!jpeg)throw Error('Could not render page '+i);
   var bytes=new Uint8Array(await jpeg.arrayBuffer());
   var img=await newPdf.embedJpg(bytes);
   var p=newPdf.addPage([img.width,img.height]);
   p.drawImage(img,{x:0,y:0,width:img.width,height:img.height});
  }
  var out=await newPdf.save({useObjectStreams:true});
  return new Blob([out],{type:'application/pdf'});
 }

 $('pdfcrun').onclick=async function(){
  var pdfC=PS.first();
  if(!pdfC)return;
  msg.textContent='Working…';
  try{
   var blob,label;
   if(pdfMode==='strong'){
    blob=await compressPdfStrong(pdfC);
    label='Strong';
   }else{
    blob=await compressPdfLight(pdfC);
    label='Light';
   }
   var pct=Math.round((1-blob.size/pdfC.size)*100);
   var change=blob.size<pdfC.size?(pct+'% smaller'):(blob.size>pdfC.size?'slightly larger':'similar size');
   downloadBlob(blob,pdfC.name.replace(/\.pdf$/i,'')+'-'+label.toLowerCase()+'.pdf',
    size(pdfC.size)+' → '+size(blob.size)+' · '+label+' · '+change);
  }catch(e){
   console.error(e);
   err(pdfMode==='strong'
     ?'Strong compress failed. Try Light mode, or the PDF may be protected.'
     :'This PDF could not be rebuilt. It may be encrypted or malformed.');
  }
 };

