  /* ---------------- Edit PDF (rotate, delete, reorder, edit page, add images) ---------------- */
  var EP={items:[],doc:null,bytes:null,name:'edited',sel:0,src:null,pages:0,failed:null,loading:null};
  /* EP is the editable WORKING copy of PDFShared.files[0]. It differs from the original only when pages were changed. */
  function epIsDirty(){
   if(!EP.items.length)return false;
   if(!EP.src)return true;
   if(EP.items.length!==EP.pages)return true;
   return EP.items.some(function(it,i){return it.t!=='pdf'||it.idx!==i||(it.rot||0)!==0})}
  function epReset(){EP.items=[];EP.doc=null;EP.bytes=null;EP.sel=0;EP.src=null;EP.pages=0;EP.failed=null;epRender();var o=$('scout2');if(o)o.classList.remove('show')}
  function epFail(f){EP.items=[];EP.doc=null;EP.bytes=null;EP.sel=0;EP.src=null;EP.pages=0;EP.failed=f;epRender()}
  function epSync(){var f=PS.first();if(!f||EP.src===f||EP.failed===f||EP.loading===f)return;epLoad(f)}
  PS.edit={isDirty:epIsDirty,reset:epReset,pending:function(){var f=PS.first();return !!f&&EP.src!==f&&EP.failed!==f}};
  PS.on(function(){if(PS.tool==='pdfedit')epSync()});
